import { spawnSync } from 'node:child_process'
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'

const suites = fs.readdirSync('test').filter((f) => f.endsWith('.selftest.mjs')).map((f) => path.join('test', f))
let failed = 0
for (const file of suites) {
  // 每个套件在独立的临时 DSH_HOME 里跑
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'dsh-'))
  const env = { ...process.env, DSH_HOME: tmp }
  const r = spawnSync(process.execPath, [file], { env, encoding: 'utf8' })
